//page2
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

const Page2 = () => {
  const [confirmedOrders, setConfirmedOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [orderDetailsToShow, setOrderDetailsToShow] = useState(null);  // Track which order's details to show
  const navigate = useNavigate();

  useEffect(() => {
    const fetchConfirmedOrders = async () => {
      try {
        const response = await axios.get('http://localhost:5000/api/orders/confirmed-orders');
        console.log('API Response:', response.data);  // Log the response data
        setConfirmedOrders(response.data);
      } catch (error) {
        console.error('Error fetching confirmed orders:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchConfirmedOrders();
  }, []);

  if (loading) return <div>Loading...</div>;  // Handle loading state

  const handleShipClick = (order) => {
    // Toggle to show/hide the address details for the selected order
    setOrderDetailsToShow(order.orderId === orderDetailsToShow ? null : order.orderId);
    console.log("Order Details to Show:", orderDetailsToShow); // Debugging toggle state
  };

  return (
    <div className="confirmed-orders-container">
      <h2>Confirmed Orders</h2>
      {confirmedOrders.length === 0 ? (
        <p>No confirmed orders available.</p>
      ) : (
        <table className="order-table">
          <thead>
            <tr>
              <th>Order ID</th>
              <th>Product Name</th>
              <th>Delivery Type</th>
              <th>Shipment Status</th>
            </tr>
          </thead>
          <tbody>
            {confirmedOrders.map((order, index) => {
              console.log('Order data:', order);  // Log individual order data

              // Check if each order has AddressCity and AddressState
              console.log('AddressCity:', order.AddressCity);
              console.log('AddressState:', order.AddressState);

              // Find the 'Order Shipped' status in the order's status array
              const shippedStatus = order.status?.find(
                (stage) => stage.stage === 'Shipped'
              );
              console.log('Shipped Status:', shippedStatus);

              return (
                <tr key={index}>
                  <td>{order.orderId}</td>
                  <td>{order.productName}</td>
                  <td>{order.deliveryType}</td>
                  <td>
                    {orderDetailsToShow === order.orderId ? (
                      // Display AddressCity and AddressState if toggled
                      order.AddressCity && order.AddressState ? (
                        <>
                          <p>{`${order.AddressCity}, ${order.AddressState}`}</p>
                          <button onClick={() => handleShipClick(order)}>Hide Details</button>
                        </>
                      ) : (
                        <p>No Address Details Available</p>
                      )
                    ) : shippedStatus ? (
                      shippedStatus.completed ? (
                        'Shipped'
                      ) : (
                        <button onClick={() => handleShipClick(order)}>Ship</button>  // Show 'Ship' button
                      )
                    ) : (
                      'Not Available'
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default Page2;
